<?php

declare(strict_types=1);

namespace App\Models;

use App\States\PanelCertificate\Active;
use App\States\PanelCertificate\PanelCertificateState;
use App\States\PanelCertificate\Retiring;
use App\States\PanelCertificate\Revoked;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Carbon;
use Override;
use Spatie\ModelStates\HasStates;

/**
 * Model representing an mTLS client certificate generated by the control panel.
 *
 * @property int $id
 * @property string $certificate
 * @property string $private_key
 * @property string $fingerprint
 * @property Carbon $not_before
 * @property Carbon $not_after
 * @property PanelCertificateState $status
 * @property int|null $active_marker
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 *
 * @method static Builder<static> active()
 * @method static Builder<static> retiring()
 */
final class PanelCertificate extends Model
{
    use HasStates;

    public const STATUS_ACTIVE = 'active';

    public const STATUS_RETIRING = 'retiring';

    public const STATUS_REVOKED = 'revoked';

    /**
     * The attributes that are mass assignable.
     *
     * @var list<string>
     */
    protected $fillable = [
        'certificate',
        'private_key',
        'fingerprint',
        'not_before',
        'not_after',
        'status',
        'active_marker',
    ];

    /**
     * Bootstrap the model and its traits.
     */
    #[Override]
    protected static function booted(): void
    {
        self::saving(function (self $cert): void {
            $cert->active_marker = $cert->status->equals(Active::class) ? 1 : null;
        });
    }

    /**
     * The attributes that should be hidden for serialization.
     *
     * @var list<string>
     */
    protected $hidden = [
        'private_key',
    ];

    /**
     * Get the attributes that should be cast.
     *
     * @return array<string, string>
     */
    #[Override]
    protected function casts(): array
    {
        return [
            'private_key' => 'encrypted',
            'not_before' => 'datetime',
            'not_after' => 'datetime',
            'status' => PanelCertificateState::class,
            'active_marker' => 'integer',
        ];
    }

    /**
     * Scope a query to only include active certificates.
     *
     * @param  Builder<$this>  $query
     */
    public function scopeActive(Builder $query): void
    {
        $query->where('status', Active::$name);
    }

    /**
     * Scope a query to only include retiring certificates.
     *
     * @param  Builder<$this>  $query
     */
    public function scopeRetiring(Builder $query): void
    {
        $query->where('status', Retiring::$name);
    }

    /**
     * Determine if this certificate has expired.
     */
    public function isExpired(): bool
    {
        return $this->not_after->isPast();
    }

    /**
     * Determine if certificate is still usable for connections (active or retiring, not expired).
     */
    public function isUsable(): bool
    {
        if ($this->status->equals(Revoked::class)) {
            return false;
        }

        return ! $this->isExpired();
    }

    /**
     * Check if certificate is expiring within a given number of days.
     */
    public function isExpiringSoon(int $days = 30): bool
    {
        return $this->not_after->diffInDays(now(), false) >= -$days && ! $this->isExpired();
    }
}
